/** Figma node `40002187:58446` — Size=Desktop, State=Default, Type=Wishlist, Unavailable=False. */
export const Wishlist_Desktop_Default: Story = {
  name: 'Wishlist — Desktop — Default (40002187:58446)',
  decorators: widthDecorator('288px'),
  args: { ...WISHLIST_BASE, id: 'coverage-wishlist-desktop-default' },
};

/** Figma node `40002187:58452` — Size=Desktop, State=Default, Type=Wishlist, Unavailable=True. */
export const Wishlist_Desktop_Unavailable: Story = {
  name: 'Wishlist — Desktop — Unavailable (40002187:58452)',
  decorators: widthDecorator('288px'),
  args: { ...WISHLIST_BASE, id: 'coverage-wishlist-desktop-unavailable', isUnavailable: true, onNotifyMe: fn() },
};

/** Figma node `40002187:58470` — Size=Mobile, State=Default, Type=Wishlist, Unavailable=False. */
export const Wishlist_Mobile_Default: Story = {
  name: 'Wishlist — Mobile — Default (40002187:58470)',
  decorators: widthDecorator('179px'),
  args: { ...WISHLIST_BASE, id: 'coverage-wishlist-mobile-default' },
};

/** Figma node `40002187:58473` — Size=Mobile, State=Default, Type=Wishlist, Unavailable=True. */
export const Wishlist_Mobile_Unavailable: Story = {
  name: 'Wishlist — Mobile — Unavailable (40002187:58473)',
  decorators: widthDecorator('179px'),
  args: { ...WISHLIST_BASE, id: 'coverage-wishlist-mobile-unavailable', isUnavailable: true, onNotifyMe: fn() },
};

// ---------------------------------------------------------------------------------------------
// Hero — excluded. See this file's own top-of-file docblock for the full investigation.

/**
 * Not a real render — Hero (`40004599:89265`, `40004638:120484`) is a confirmed orphaned design
 * node with no owning ticket and no fourth `variation` value to render it with. Kept as its own

/** Out-of-stock: the bag button is present but disabled, and the notify-me CTA takes its place
 *  as the available action. */
export const Unavailable: Story = {
  args: {
    ...Default.args,
    isUnavailable: true,
    showNotifyMe: true,
    onNotifyMe: fn(),
  },
};

/** A variant re-fetch in progress — ZimmProductPrice renders its own invisible placeholder,
 *  preserving the layout slot rather than collapsing it. */
export const LoadingPrice: Story = {
  args: {
    ...Default.args,
    currentPrice: undefined,
    isPriceLoading: true,
  },
};

