  allChips: Array.from(doc.querySelectorAll('[data-size-value]')).map(el => ({
    value: el.getAttribute('data-size-value'),
    ariaChecked: el.getAttribute('aria-checked'),
    tabIndex: el.tabIndex,
  })),
});

const iframe = document.getElementById('storybook-preview-iframe');
const doc = iframe.contentDocument;
const active = doc.activeElement;
const before = active?.getAttribute('data-size-value');

const event = new KeyboardEvent('keydown', { key: 'ArrowRight', code: 'ArrowRight', bubbles: true, cancelable: true });
active.dispatchEvent(event);

await new Promise(r => setTimeout(r, 100));

const activeAfter = doc.activeElement;
JSON.stringify({
  before,
  activeAfterTag: activeAfter?.tagName,
  activeAfterValue: activeAfter?.getAttribute('data-size-value'),
  allChips: Array.from(doc.querySelectorAll('[data-size-value]')).map(el => ({
    value: el.getAttribute('data-size-value'),
    ariaChecked: el.getAttribute('aria-checked'),
  })),
});

